// 配置 MySQL 连接池
const pool = mysql.createPool({
    host: 'localhost',
    user: 'root',
    password: '100911yzpYZP',
    database: 'wclaw_db',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// 初始化数据库和表
async function initDB() {
    try {
        // 先连接不带 database 的，创建数据库
        const tempPool = mysql.createPool({
            host: 'localhost',
            user: 'root',
            password: '100911yzpYZP'
        });
        await tempPool.query("CREATE DATABASE IF NOT EXISTS wclaw_db DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
        await tempPool.end();

        // 创建 users 表，注意去除了 phone 的 UNIQUE 约束
        await pool.query(`
            CREATE TABLE IF NOT EXISTS users (
                id INT AUTO_INCREMENT PRIMARY KEY,
                username VARCHAR(50) NOT NULL UNIQUE,
                password VARCHAR(100) NOT NULL,
                phone VARCHAR(20) NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        `);

        // 创建 history 表
        await pool.query(`
            CREATE TABLE IF NOT EXISTS history (
                id INT AUTO_INCREMENT PRIMARY KEY,
                msg_id VARCHAR(50) NOT NULL,
                username VARCHAR(50) NOT NULL,
                role VARCHAR(10) NOT NULL,
                content TEXT NOT NULL,
                status VARCHAR(20) DEFAULT 'success',
                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        `);

        // 创建 feedbacks 表
        await pool.query(`
            CREATE TABLE IF NOT EXISTS feedbacks (
                id INT AUTO_INCREMENT PRIMARY KEY,
                username VARCHAR(50) NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        `);

        // 创建 favorites 表
        await pool.query(`
            CREATE TABLE IF NOT EXISTS favorites (
                id INT AUTO_INCREMENT PRIMARY KEY,
                username VARCHAR(50) NOT NULL,
                msg_id VARCHAR(50) NOT NULL,
                content TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY unique_fav (username, msg_id)
            )
        `);

        // 创建 notifications 表
        await pool.query(`
            CREATE TABLE IF NOT EXISTS notifications (
                id INT AUTO_INCREMENT PRIMARY KEY,
                content TEXT NOT NULL,
                is_active BOOLEAN DEFAULT TRUE,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        `);

        console.log("MySQL 数据库和表初始化成功！");
    } catch (err) {
        console.error("MySQL 初始化失败，请检查账号密码是否正确，或者 mysql 服务是否启动:", err);
    }
}

// 辅助函数：保存聊天记录
async function saveChatHistory(username, role, content, status = 'success') {
    // 根据用户隐私要求，不再将聊天记录保存在后台数据库
