// 存储永久的通知 SSE 连接 (username -> Array of Response objects)
const notificationClients = new Map();

// Webhook 接收口：OpenClaw cron/webhook 通过此处推送消息
app.post('/api/notify', (req, res) => {
    const { content, username } = req.body;
    if (!content) return res.status(400).json({ code: 400, message: '缺少 content' });

    const targetUser = username || 'ad1009'; // 默认推送给 ad1009
    console.log(`[通知 webhook] 收到推送: user=${targetUser}, content=${content.substring(0, 50)}`);

    const clients = notificationClients.get(targetUser);
    if (clients && clients.length > 0) {
        const payload = JSON.stringify({
            type: 'notification',
            data: { content, timestamp: Date.now() }
        });
        clients.forEach(clientRes => {
            try {
                clientRes.write(`data: ${payload}\n\n`);
            } catch(e) {
                console.log(`[通知 webhook] 写入失败: ${e.message}`);
            }
        });
        res.json({ code: 200, message: '已推送到' + clients.length + '个客户端' });
    } else {
        // 没有在线客户端，缓存消息（保留最近20条）
        if (!global.pendingNotifications) global.pendingNotifications = {};
        if (!global.pendingNotifications[targetUser]) global.pendingNotifications[targetUser] = [];
        global.pendingNotifications[targetUser].push({ content, timestamp: Date.now() });
        if (global.pendingNotifications[targetUser].length > 20) {
            global.pendingNotifications[targetUser].shift();
        }
        console.log(`[通知 webhook] 用户 ${targetUser} 不在线，已缓存`);
        res.json({ code: 200, message: '用户离线，已缓存' });
    }
});

// 持久化通知 SSE：前端登录后永久保持此连接
app.get('/api/notifications/stream', (req, res) => {
    const token = req.query.token;
    if (!token) return res.status(401).json({ code: 401, message: '未提供 Token' });

    try {
        const decoded = jwt.verify(token, JWT_SECRET);
        const username = decoded.username;

        console.log(`[通知 SSE] ${username} 建立持久化通知连接`);

        res.setHeader('Content-Type', 'text/event-stream');
        res.setHeader('Cache-Control', 'no-cache');
        res.setHeader('Connection', 'keep-alive');
        res.flushHeaders();

        // 注册客户端
        if (!notificationClients.has(username)) {
            notificationClients.set(username, []);
        }
        notificationClients.get(username).push(res);

        // 发送初始连接成功事件
        res.write(`data: ${JSON.stringify({ type: 'connected', data: { message: '通知通道已建立' } })}\n\n`);

        // 发送缓存的离线消息
        if (global.pendingNotifications && global.pendingNotifications[username]) {
            const cached = global.pendingNotifications[username];
            cached.forEach(msg => {
                res.write(`data: ${JSON.stringify({ type: 'notification', data: msg })}\n\n`);
            });
            delete global.pendingNotifications[username];
            console.log(`[通知 SSE] 已发送 ${cached.length} 条缓存消息给 ${username}`);
        }

        // 心跳保活（每30秒）
        const heartbeatTimer = setInterval(() => {
            try {
                res.write(': hb\n\n');
            } catch(e) {
                clearInterval(heartbeatTimer);
            }
        }, 30000);

        req.on('close', () => {
            clearInterval(heartbeatTimer);
            // 从列表中移除
            if (notificationClients.has(username)) {
                const arr = notificationClients.get(username);
                const idx = arr.indexOf(res);
                if (idx > -1) arr.splice(idx, 1);
                if (arr.length === 0) notificationClients.delete(username);
            }
            console.log(`[通知 SSE] ${username} 断开连接`);
        });

    } catch (err) {
        console.error('[通知 SSE] Token 验证失败:', err.message);
        res.status(401).json({ code: 401, message: 'Token 无效' });
    }
});

