// ================= 持久化通知 SSE 连接 =================
// 独立于命令周期的永久 SSE 连接，用于接收系统通知/定时任务消息
let notificationSource = null;
let notificationReconnectTimer = null;

function connectNotificationSSE() {
    if (!currentToken || !currentUser) return;

    // 如果已有连接且状态正常，不重复创建
    if (notificationSource && notificationSource.readyState !== EventSource.CLOSED) {
        return;
    }

    // 清理旧的连接
    if (notificationSource) {
        notificationSource.close();
        notificationSource = null;
    }
    if (notificationReconnectTimer) {
        clearTimeout(notificationReconnectTimer);
        notificationReconnectTimer = null;
    }

    const url = host + '/api/notifications/stream?token=' + encodeURIComponent(currentToken);
    console.log('[通知 SSE] 正在连接:', url);

    notificationSource = new EventSource(url);

    notificationSource.onopen = function() {
        console.log('[通知 SSE] 连接已建立');
    };

    notificationSource.onmessage = function(event) {
        try {
            const data = JSON.parse(event.data);
            if (data.type === 'notification' && data.data && data.data.content) {
                console.log('[通知 SSE] 收到消息:', data.data.content);
                // 将通知显示到当前聊天框
                showNotificationMessage(data.data.content);
            } else if (data.type === 'connected') {
                console.log('[通知 SSE]', data.data.message);
            }
        } catch(e) {
            console.error('[通知 SSE] 解析消息失败:', e);
        }
    };

    notificationSource.onerror = function() {
        console.log('[通知 SSE] 连接断开，5秒后重连...');
        notificationSource.close();
        notificationSource = null;
        // 5秒后自动重连
        notificationReconnectTimer = setTimeout(function() {
            console.log('[通知 SSE] 正在重连...');
            connectNotificationSSE();
        }, 5000);
    };
}

// 将系统通知显示为 AI 消息气泡
function showNotificationMessage(content) {
    const chatBox = document.getElementById('chat-box');
    if (!chatBox) return;

    const msgId = 'notify-' + Date.now();
    const now = new Date();
    const time = now.toLocaleTimeString('zh-CN', {hour: '2-digit', minute:'2-digit', second:'2-digit'});
    const date = now.toLocaleDateString('zh-CN', {year: 'numeric', month: '2-digit', day: '2-digit'}).replace(/\//g, '-');
    const fullTime = date + ' ' + time;

    const bubble = document.createElement('div');
    bubble.className = 'msg-row ai';
    bubble.innerHTML = `
        <div class="msg-bubble notify-msg" id="${msgId}">
            <div class="notify-header">
                <i class="fa-solid fa-bell" style="color: #ff9500; margin-right: 6px;"></i>
                <span style="font-size: 0.8em; color: #888;">系统通知</span>
            </div>
            <div style="margin-top: 4px;">${escapeHtml(content)}</div>
        </div>
        <div class="msg-time">
            <span class="backend-badge openclaw">通知</span>
            ${fullTime}
        </div>`;

    chatBox.appendChild(bubble);
    scrollToBottom();

    // 触发通知提醒
    triggerNotify();
}

