    // 兼容 OpenClaw webhook 标准格式以及自定义格式
    let content = '';
    let username = '';

    if (req.body && req.body.summary) {
        // OpenClaw webhook 标准格式：{ "id": "...", "summary": "...", "status": "...", ... }
        content = req.body.summary || '';
        username = req.body.username || 'ad1009';
    } else if (req.body && req.body.content) {
        // 自定义格式
        content = req.body.content;
        username = req.body.username || 'ad1009';
    } else if (req.body && req.body.text) {
        // 纯文本格式
        content = req.body.text;
        username = req.body.username || 'ad1009';
    } else if (typeof req.body === 'string') {
        content = req.body;
        username = 'ad1009';
    } else {
        // 兜底
        content = JSON.stringify(req.body || '');
        username = 'ad1009';
    }

    // 清理内容中的 Markdown 和多余换行
    content = content.replace(/[#*_`~\[\]]/g, '').replace(/\n{3,}/g, '\n\n').trim();
    if (!content) {
        return res.status(400).json({ code: 400, message: '内容为空' });
    }

    console.log(`[cron webhook] 收到: user=${username}, content=${content.substring(0, 80)}`);

    const clients = notificationClients.get(username);
    if (clients && clients.length > 0) {
        const payload = JSON.stringify({
            type: 'notification',
            data: { content, timestamp: Date.now() }
        });
        clients.forEach(clientRes => {
            try {
                clientRes.write(`data: ${payload}\n\n`);
            } catch(e) {
                console.log(`[cron webhook] 写入失败: ${e.message}`);
            }
        });
        console.log(`[cron webhook] 已推送到 ${clients.length} 个客户端`);
        res.json({ code: 200, message: 'ok' });
    } else {
        // 缓存消息
        if (!global.pendingNotifications) global.pendingNotifications = {};
        if (!global.pendingNotifications[username]) global.pendingNotifications[username] = [];
        global.pendingNotifications[username].push({ content, timestamp: Date.now() });
        if (global.pendingNotifications[username].length > 20) {
            global.pendingNotifications[username].shift();
        }
        console.log(`[cron webhook] 用户 ${username} 离线，已缓存`);
        res.json({ code: 200, message: 'cached' });
    }
});

